from collections import deque, Counter

def components(grid, rows, cols, bg, conn=4, include=None):
    H,W=len(grid),len(grid[0]); cells={(r,c) for r in rows for c in cols if (include is None or grid[r][c] in include) and grid[r][c]!=bg}
    moves=[(-1,0),(1,0),(0,-1),(0,1)]
    if conn==8: moves += [(-1,-1),(-1,1),(1,-1),(1,1)]
    comps=[]
    while cells:
        start=min(cells); cells.remove(start); q=[start]; comp={start}
        while q:
            r,c=q.pop()
            for dr,dc in moves:
                p=(r+dr,c+dc)
                if p in cells:
                    cells.remove(p); comp.add(p); q.append(p)
        comps.append(comp)
    return sorted(comps,key=lambda x:min(x))

def describe(grid, comps):
    for k,co in enumerate(comps):
        rs=[r for r,c in co]; cs=[c for r,c in co]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        print(k,'bbox',(r0,r1,c0,c1),'size',len(co),'colors',Counter(grid[r][c] for r,c in co))
        for r in range(r0,r1+1):
            print(' ', ''.join('.' if (r,c) not in co else str(grid[r][c]) for c in range(c0,c1+1)))
        print()
