def normalize(cells):
    mr=min(r for r,c in cells); mc=min(c for r,c in cells)
    return {(r-mr,c-mc) for r,c in cells}
def transformations_color(cells, allow_reflect=True):
    # D4 map cell coords; emit dict mapping new coord -> color and normalized
    out=[]
    variants=[]
    for refl in ([False,True] if allow_reflect else [False]):
        for rot in range(4):
            d={}
            for (r,c),v in cells.items():
                if refl: c1=-c; r1=r
                else: r1,c1=r,c
                for _ in range(rot): r1,c1=c1,-r1
                d[(r1,c1)]=v
            mr=min(r for r,c in d); mc=min(c for r,c in d)
            d={(r-mr,c-mc):v for (r,c),v in d.items()}
            sig=tuple(sorted(d.items()))
            if sig not in [x[0] for x in variants]: variants.append((sig,d,rot,refl))
    return variants

def placements_for_piece(piece, target, allow_transform=False):
    vars=transformations_color(piece['cells']) if allow_transform else [(None,piece['cells'],0,False)]
    res=[]
    for _,cells,rot,refl in vars:
        maxr=max(r for r,c in cells); maxc=max(c for r,c in cells)
        for r0 in range(10-maxr):
            for c0 in range(25-maxc):
                glob={(r0+r,c0+c) for r,c in cells}
                if glob<=target:
                    bit=0
                    for r,c in glob: bit |= 1 << (r*25+c)
                    res.append({'piece':piece['id'],'origin':(r0,c0),'cells':cells,'glob':glob,'bit':bit,'rot':rot,'refl':refl})
    return res

def solve_exact(pieces, target, allow_transform=False, max_solutions=2):
    allplacements=[]
    for p in pieces: allplacements.extend(placements_for_piece(p,target,allow_transform))
    bypiece={p['id']:[] for p in pieces}
    bycell={x:[] for x in target}
    for pl in allplacements:
        bypiece[pl['piece']].append(pl)
        for x in pl['glob']: bycell[x].append(pl)
    full=0
    for r,c in target: full|=1 << (r*25+c)
    sols=[]
    # id to piece area; candidate identify placement
    def rec(covered, used, chosen):
        if covered==full:
            if len(used)==len(pieces): sols.append(list(chosen))
            return len(sols)>=max_solutions
        # choose uncovered cell with least viable options over unused pieces
        remaining=full^covered
        best=None; optsbest=None
        while remaining:
            bit=remaining & -remaining
            idx=bit.bit_length()-1
            pos=(idx//25,idx%25)
            opts=[]
            for pl in bycell[pos]:
                pid=pl['piece']
                if pid in used: continue
                if pl['bit'] & covered: continue
                opts.append(pl)
            if optsbest is None or len(opts)<len(optsbest):
                best=pos; optsbest=opts
                if len(opts)==0: return False
                if len(opts)==1: break
            remaining^=bit
        for pl in optsbest or []:
            if rec(covered|pl['bit'], used|{pl['piece']}, chosen+[pl]): return True
        return False
    rec(0,set(),[])
    return sols, {pid:len(p) for pid,p in bypiece.items()},allplacements
