def samecolor_components(grid, rows, cols, bg):
    H,W=len(grid),len(grid[0]); cells={(r,c) for r in rows for c in cols if grid[r][c]!=bg}
    comps=[]
    while cells:
        st=min(cells); cells.remove(st); col=grid[st[0]][st[1]]; q=[st]; comp={st}
        while q:
            r,c=q.pop()
            for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                p=(r+dr,c+dc)
                if p in cells and grid[p[0]][p[1]]==col:
                    cells.remove(p); comp.add(p); q.append(p)
        comps.append(comp)
    return sorted(comps,key=lambda x:min(x))
